<script>
 import {onMount,tick} from 'svelte';
 let maxDraftChars=200000;
 let logged=false,password='',csrf='',error='',notice='',busy=false,accounts=[],messages=[],drafts=[],filter='all',page=0,hasMore=false,view='inbox',reader=null,editor=null,settings=null,dirty=false;
 const emptyEndpoint=(port)=>({host:'',port,tls:'implicit',user:'',password:''});
 const describe={LOGIN_REQUIRED:'Sessie verlopen. Meld opnieuw aan; invoer blijft in deze open tab.',LOGIN_FAILED:'Aanmelden mislukt.',TRY_LATER:'Te veel pogingen. Wacht even.',REQUEST_FAILED:'Actie mislukt. Controleer invoer, verbinding en serverconfiguratie.',DRAFT_CONFLICT:'Concept gewijzigd of account niet beschikbaar. Je invoer is behouden; overschrijf niet blind.',SEND_LOCKED:'Deze verzendoperatie staat vast. Niet opnieuw versturen.',ACCOUNT_HAS_DRAFTS:'Account heeft concepten/verzendhistorie en kan nog niet verwijderd worden.'};
 async function api(path,method='GET',data){
  let response;try{response=await fetch(path,{method,headers:{'Content-Type':'application/json','x-csrf-token':csrf},...(data?{body:JSON.stringify(data)}:{})});}catch{throw new Error('Geen verbinding. Invoer niet automatisch opgeslagen. Niet sluiten of herladen.');}
  const value=await response.json();if(!response.ok){if(response.status===401)logged=false;throw new Error(describe[value.error]||value.error||'Actie mislukt');}return value;
 }
 async function action(fn){if(busy)return;busy=true;error='';try{await fn();}catch(e){error=e.message;}finally{busy=false;}}
 async function refresh(){maxDraftChars=(await api('/api/config')).maxDraftChars;accounts=await api('/api/accounts');if(view==='inbox'){const r=await api(`/api/inbox?account=${filter}&page=${page}`);messages=r.messages;hasMore=r.hasMore;if(r.errors.length)error='Inbox onvolledig: '+r.errors.map(e=>accounts.find(a=>a.id===e.accountId)?.label||'account').join(', ')+'. Controleer verbinding/TLS/aanmelding bij Accounts.';}drafts=await api('/api/drafts');}
 async function login(){await action(async()=>{const r=await api('/api/login','POST',{password});password='';csrf=r.csrf;logged=true;await refresh();});}
 async function logout(){await action(async()=>{if(dirty&&!confirm('Niet-opgeslagen invoer gaat bij uitloggen verloren. Toch uitloggen?'))return;await api('/api/logout','POST',{});logged=false;csrf='';accounts=[];messages=[];drafts=[];reader=null;editor=null;settings=null;dirty=false;notice='';});}
 function newDraft(reply){editor={id:crypto.randomUUID(),accountId:reply?.accountId||(filter==='all'?'':filter),revision:0,to:reply?.replyTo||'',subject:reply?'Re: '+reply.subject:'',text:reply?'\n\n'+reply.text:'',operation:null};dirty=true;view='compose';reader=null;notice='Nog niet opgeslagen. Sluiten/herladen kan invoer verliezen.';}
 async function save(){const r=await api(`/api/drafts/${editor.id}`,'PUT',{accountId:editor.accountId,revision:editor.revision,to:editor.to,subject:editor.subject,text:editor.text});editor={...editor,revision:r.revision};dirty=false;notice='Opgeslagen op Shott Mail, niet gesynchroniseerd naar IMAP Drafts.';}
 async function send(){await action(async()=>{if(editor.operation)return;await save();editor={...editor,operation:{state:'preparing'}};notice='Verzending wordt aangeboden; niet opnieuw versturen.';try{const op=await api(`/api/drafts/${editor.id}/send`,'POST',{revision:editor.revision});editor={...editor,operation:op};notice=status(op);}catch(e){editor={...editor,operation:{state:'outcome_unknown'}};notice=status(editor.operation);throw e;}});}
 async function checkSend(){await action(async()=>{const d=await api(`/api/drafts/${editor.id}`);editor={...editor,operation:d.operation};notice=d.operation?status(d.operation):'Geen verzendoperatie geregistreerd; concept behouden.';});}
 function status(op){return ({preparing:'Voorbereiding loopt. Controleer status; niet opnieuw verzenden.',submitting:'Verzending loopt. Niet opnieuw verzenden.',accepted:'SMTP-server heeft geaccepteerd; dit bewijst geen aflevering. Tekst lokaal bewaard; geen IMAP Sent-kopie gemaakt.',partial_recipients:'Gedeeltelijk geaccepteerd. Niet opnieuw naar iedereen versturen.',outcome_unknown:'Uitkomst onbekend: mogelijk al verzonden. Controleer bij ontvanger/provider; ontbreken van een Sent-kopie bewijst niets. Niet blind opnieuw versturen.',failed_before_submit:'Niet aangeboden: verbinding/TLS/auth/configuratie faalde. Tekst behouden. Deze operatie blijft geblokkeerd; maak pas na controle bewust een nieuw bericht.'})[op?.state]||'';}
 async function openMail(m){await action(async()=>{reader=await api(`/api/messages/${m.accountId}/${m.validity}/${m.uid}`);await tick();document.getElementById('readtitle')?.focus();});}
 function editAccount(a){settings=a?structuredClone(a):{label:'',address:'',imap:emptyEndpoint(993),smtp:emptyEndpoint(465)};settings.imap.password='';settings.smtp.password='';view='accounts';notice='';}
 async function saveAccount(){await action(async()=>{const data={label:settings.label,address:settings.address,imap:settings.imap,smtp:settings.smtp};const result=await api(settings.id?`/api/accounts/${settings.id}`:'/api/accounts',settings.id?'PUT':'POST',data);settings.id=result.id;settings.imap.password='';settings.smtp.password='';accounts=await api('/api/accounts');notice='Account opgeslagen. Test IMAP en SMTP afzonderlijk; opslaan bewijst geen verbinding.';});}
 async function testAccount(){await action(async()=>{const result=await api(`/api/accounts/${settings.id}/test`,'POST',{});notice=`IMAP: ${result.imap}; SMTP: ${result.smtp}. Geen testmail verzonden. Bij fouten: controleer hostallowlist, CA/TLS en credentials.`;});}
 function leaveWarning(e){if(dirty){e.preventDefault();e.returnValue='';}}
 onMount(()=>{action(async()=>{try{const r=await api('/api/session');csrf=r.csrf;logged=true;await refresh();}catch{logged=false;error='';}});});
</script>
<svelte:window onbeforeunload={leaveWarning}/>
<header><div class="brand"><span class="mark">s</span> Shott Mail</div><span class="tag">B1 · IMAP / SMTP</span>{#if logged}<button onclick={logout} disabled={busy}>Uitloggen</button>{/if}</header>
{#if !logged}
 <main class="login"><h1>Een rustige plek voor je mail.</h1><p>Eigen Shott Mail-login. Eerste wachtwoord staat in het lokaal gegenereerde secretbestand.</p><form onsubmit={e=>{e.preventDefault();login();}}><label>Wachtwoord<input type="password" autocomplete="current-password" bind:value={password} required/></label><button class="primary" disabled={busy}>Aanmelden</button></form>{#if editor}<p>Je actieve concept blijft in deze open tab. Niet herladen.</p>{/if}</main>
{:else}
 <div class="shell" class:reading={!!reader}>
  <aside><div class="eyebrow">JOUW MAILBOXEN</div><label>Account<select bind:value={filter} onchange={()=>action(async()=>{reader=null;page=0;view='inbox';await refresh();})}><option value="all">Alle accounts</option>{#each accounts as a}<option value={a.id}>{a.label} · {a.address}</option>{/each}</select></label><button class="primary" onclick={()=>newDraft(null)} disabled={!!editor&&dirty}>+ Nieuw bericht</button><nav><button onclick={()=>action(async()=>{reader=null;view='inbox';await refresh();})}>Inbox</button><button onclick={()=>action(async()=>{reader=null;view='drafts';await refresh();})}>Concepten / verzendstatus</button><button onclick={()=>{reader=null;view='accounts';}}>Accounts</button>{#if editor}<button onclick={()=>view='compose'}>Actief concept hervatten</button>{/if}</nav><p class="motto">Een rustige plek<br/>voor al je mail.</p></aside>
  <main class="workspace">
  {#if view==='inbox'}
   <section class="list"><div class="listhead"><div class="eyebrow">JE OVERZICHT</div><h1>Inbox</h1><button onclick={()=>action(refresh)} disabled={busy}>Vernieuwen</button><p>Pagina {page+1} per account · nieuwste eerst</p></div>{#each messages as m}<button class="mail" onclick={()=>openMail(m)}><span>{m.unread?'● ':''}{m.from}</span><strong>{m.subject}</strong><span class="tag">{m.accountLabel} · {m.address}</span></button>{/each}{#if !messages.length}<p class="empty">Geen berichten geladen.{accounts.length?'':' Voeg eerst een account toe.'}</p>{/if}<div class="actions"><button disabled={page===0||busy} onclick={()=>action(async()=>{page--;await refresh();})}>Nieuwere</button><button disabled={!hasMore||busy} onclick={()=>action(async()=>{page++;await refresh();})}>Oudere</button></div></section>
   <section class="reader">{#if reader}<button onclick={()=>reader=null}>← Terug naar lijst</button><span class="tag">{reader.accountLabel} · {reader.address}</span><h2 id="readtitle" tabindex="-1">{reader.subject}</h2><p>{reader.from}</p><p class="note">Veilige weergave: externe afbeeldingen, links en actieve inhoud zijn uitgeschakeld.</p>{#if reader.html}<iframe title="Veilige berichtinhoud" sandbox="" srcdoc={'<!doctype html><meta http-equiv="Content-Security-Policy" content="default-src &#39;none&#39;; form-action &#39;none&#39;; base-uri &#39;none&#39;"><meta charset="utf-8">'+reader.html}></iframe><details><summary>Tekstweergave</summary><pre>{reader.text}</pre></details>{:else}<pre>{reader.text}</pre>{/if}{#if reader.attachments.length}<p>Bijlagen aanwezig; downloaden volgt na B1.</p>{/if}<button class="primary" onclick={()=>newDraft(reader)} disabled={!!editor&&dirty}>Beantwoorden</button>{:else}<p class="empty">Selecteer een bericht.</p>{/if}</section>
  {:else if view==='compose' && editor}
   <section class="panel"><h1>Bericht opstellen</h1><p class="note">Tekstbericht, één ontvanger. Bewaren gebeurt op Shott Mail. Geen automatische verzending of offline-opslag.</p><form onsubmit={e=>{e.preventDefault();send();}} oninput={()=>dirty=true}><fieldset disabled={!!editor.operation||busy}><label>Van<select bind:value={editor.accountId} required disabled={editor.revision>0}><option value="">Kies bewust een afzender</option>{#each accounts as a}<option value={a.id}>{a.label} · {a.address}</option>{/each}</select></label><label>Aan<input type="email" bind:value={editor.to} required/></label><label>Onderwerp<input bind:value={editor.subject} maxlength="998"/></label><label>Bericht<textarea bind:value={editor.text} maxlength={maxDraftChars}></textarea></label><div class="actions"><button type="submit" class="primary">Verzenden</button><button type="button" onclick={()=>action(save)}>Concept bewaren</button></div></fieldset></form>{#if editor.operation}<p class="note" role="status">{status(editor.operation)}</p><button onclick={checkSend} disabled={busy}>Verzendstatus controleren</button>{/if}</section>
  {:else if view==='drafts'}
   <section class="panel"><h1>Concepten en verzendstatus</h1>{#each drafts as d}<button class="mail" onclick={()=>{if(dirty&&!confirm('Actieve onopgeslagen tekst vervangen?'))return;editor={id:d.id,accountId:d.accountId,revision:d.revision,...d.body,operation:d.operation};dirty=false;view='compose';notice='Opgeslagen versie geladen.';}}><strong>{d.body.subject||'(Geen onderwerp)'}</strong><span>{accounts.find(a=>a.id===d.accountId)?.address} → {d.body.to}</span><span class="tag">{d.operation?.state||'Concept'} · revisie {d.revision}</span></button>{/each}</section>
  {:else if view==='accounts'}
   <section class="panel"><h1>Accounts</h1><p>Alleen IMAP/SMTP met gecontroleerde TLS. Beheerder moet host:poort expliciet toestaan.</p><div class="actions">{#each accounts as a}<button onclick={()=>editAccount(a)}>{a.label}</button>{/each}<button onclick={()=>editAccount(null)}>Account toevoegen</button></div>{#if settings}<form onsubmit={e=>{e.preventDefault();saveAccount();}}><label>Naam<input bind:value={settings.label} required maxlength="80"/></label><label>Afzenderadres<input type="email" bind:value={settings.address} required/></label><div class="fields">{#each ['imap','smtp'] as protocol}<fieldset><legend>{protocol.toUpperCase()}</legend><label>Host<input bind:value={settings[protocol].host} required/></label><label>Poort<input type="number" bind:value={settings[protocol].port} min="1" max="65535" required/></label><label>TLS<select bind:value={settings[protocol].tls}><option value="implicit">Implicit TLS</option><option value="starttls">Verplicht STARTTLS</option></select></label><label>Gebruikersnaam<input bind:value={settings[protocol].user} required autocomplete="off"/></label><label>Wachtwoord{settings.id?' (leeg = behouden)':''}<input type="password" bind:value={settings[protocol].password} autocomplete="new-password" required={!settings.id}/></label></fieldset>{/each}</div><button class="primary" disabled={busy}>Account opslaan</button></form>{#if settings.id}<div class="actions"><button onclick={testAccount} disabled={busy}>Opgeslagen instellingen testen</button><button disabled={busy} onclick={()=>action(async()=>{if(confirm('Alleen lokaal account verwijderen, geen mail bij provider?')){await api(`/api/accounts/${settings.id}`,'DELETE');settings=null;accounts=await api('/api/accounts');}})}>Account verwijderen</button></div>{/if}{/if}</section>
  {/if}
  </main>
 </div>
{/if}
<div class="feedback" aria-live="polite">{#if error}<p role="alert" class="error">{error}</p>{/if}{#if notice}<p>{notice}</p>{/if}</div>
<footer>Shott Mail B1 · Geen garantie · <a href="/LICENSE">AGPL-licentie</a> · <a href="https://github.com/aaronshott/shott-mail/tree/feat/b1-mail-flow" target="_blank" rel="noreferrer noopener">Broncode</a> · Snooze en PWA-installatie volgen in v1.</footer>
